import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, userEvent, within } from 'storybook/test';
import { Footer } from './index';
import { FOOTER_FIXTURE } from './contentfulFixture';

const meta: Meta<typeof Footer> = {
  title: 'Layout/Footer',
  component: Footer,
  parameters: {
    layout: 'fullscreen',
  },
  args: {
    data: FOOTER_FIXTURE,
  },
};

export default meta;
type Story = StoryObj<typeof Footer>;

export const Default: Story = {
  render: (args) => (
    <div style={{ width: '100%' }}>
      <Footer {...args} />
    </div>
  ),
  // Asserts leavesTheSite's scheme branch. Security-adjacent: rel="noopener noreferrer" is what
  // stops the storefront URL reaching WhatsApp in the Referer header, and the accessible-name
  // suffix is WCAG 3.2.5. Nothing else in CI covered this — the behaviour was only ever verified
  // by hand, which is exactly the kind of gap that survives a refactor invisibly.
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // http(s) → new tab, hardened, and the name says so
    const whatsApp = canvas.getByRole('link', { name: /whatsapp/i });
    await expect(whatsApp).toHaveAttribute('target', '_blank');
    await expect(whatsApp).toHaveAttribute('rel', 'noopener noreferrer');
    await expect(whatsApp).toHaveAccessibleName(/opens in a new tab/i);

    // tel:/mailto: hand off to the OS — a target would do nothing, so there must not be one
    for (const name of [/call us/i, /email us/i]) {
      const link = canvas.getByRole('link', { name });
      await expect(link).not.toHaveAttribute('target');
      await expect(link).not.toHaveAccessibleName(/opens in a new tab/i);
    }
  },
};

export const Subscribed: Story = {
  args: {
    initialSubscribed: true,
  },
  render: (args) => (
    <div style={{ width: '100%' }}>
      <Footer {...args} />
    </div>
  ),
};

export const SubscribeSubmit: Story = {
..... 100-210 .....
  ),
  // Covers the dialog mechanics now owned by useSubscribeModal: focus entry, the Tab trap in
  // both wrap directions, the body-scroll lock, Escape dismissal and focus restore. Mutation-
  // tested — breaking the setTimeout focus, the Escape branch, the Tab branch or the overflow
  // write each fails this play. Before it existed, those mutations passed the whole Storybook
  // suite, so the hook extraction would have had no CI net at all.
  //
  // The one branch this cannot reach is the trap's `!el.hasAttribute('disabled')` filter:
  // nothing in SubscribeModal is ever disabled, so there is no disabled control here for it to
  // exclude. That one is covered with a synthetic harness in hooks/useSubscribeModal.test.tsx.
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Read, not assumed: the hook restores whatever inline value it found, so the release
    // assertion at the end compares against this rather than a hardcoded ''. Asserting it is
    // not ALREADY 'hidden' is what stops the lock assertion below from passing vacuously.
    const overflowBefore = document.body.style.overflow;
    await expect(overflowBefore).not.toBe('hidden');

    await userEvent.type(canvas.getByRole('textbox', { name: /email/i }), 'test@example.com');
    const trigger = canvas.getByRole('button', { name: /subscribe/i });
    await userEvent.click(trigger);

    // Portal renders outside canvasElement — testing.md §Layer-2 exception.
    const doc = within(document.body);
    const dialog = doc.getByRole('dialog');
    await expect(dialog).toBeInTheDocument();
    await expect(dialog).toHaveAttribute('aria-modal', 'true');

    // Scroll lock: the page behind a modal must not scroll out from under it.
    await expect(document.body.style.overflow).toBe('hidden');

    // Focus is moved into the dialog, onto the first field
    const firstName = doc.getByRole('textbox', { name: /first name/i });
    await expect(firstName).toHaveFocus();

    // Tab trap, both wrap directions (WCAG 2.1.2 — no keyboard trap that cannot be escaped,
    // and no tabbing out of a modal dialog). The form's focus order is firstName, lastName,
    // Privacy Policy, Cancel, Continue, so firstName is `first` and Continue is `last`.
    //
    // Continue is focused programmatically rather than clicked: it is the submit button, so a
    // click would close the dialog before the trap could be exercised. The wrap assertions are
    // sound despite userEvent moving focus itself — the hook's document-level keydown listener
    // calls preventDefault on a wrap, and userEvent skips its own focus move when the keydown
    // is defaultPrevented, so the focus observed below is the trap's and nothing else's.
    const continueButton = doc.getByRole('button', { name: /continue/i });
    continueButton.focus();
    await expect(continueButton).toHaveFocus();

    await userEvent.tab();
    await expect(firstName).toHaveFocus();

    await userEvent.tab({ shift: true });
    await expect(continueButton).toHaveFocus();

    // Escape dismisses it and focus returns to the control that opened it (WCAG 2.4.3)
    await userEvent.keyboard('{Escape}');
    await expect(doc.queryByRole('dialog')).not.toBeInTheDocument();
    await expect(trigger).toHaveFocus();

    // ...and the lock is released to whatever was there before, not blindly to ''.
    await expect(document.body.style.overflow).toBe(overflowBefore);
  },
};

/**
 * Contact channels are optional per storefront, and a value arriving from Contentful may be
 * unsafe. Both cases fall through to a labelled, non-interactive span. Adding the placeholder
 * hrefs to the fixture made that branch unreachable from every other story, so it needs its own.
 */
const FIXTURE_DEGRADED_CHANNELS = {
  ...FOOTER_FIXTURE,
  fields: {
    ...FOOTER_FIXTURE.fields,
    // absent for this storefront
    phoneHref: undefined,
    // present but rejected by isSafeHref — must never reach an anchor
    whatsAppHref: 'javascript:alert(1)',
  },
};

export const ContactChannelFallbacks: Story = {
  name: 'Contact channels — absent and unsafe',
  args: { data: FIXTURE_DEGRADED_CHANNELS },
  render: (args) => (
    <div style={{ width: '100%' }}>
      <Footer {...args} />
    </div>
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Absent and unsafe both render the icon as a labelled span: no href, no tab stop, so
    // nothing promises an action that cannot be performed (WCAG 2.4.4 / 3.2.4) — but the
    // channel stays perceivable rather than silently disappearing.
    for (const name of [/call us/i, /whatsapp/i]) {
      await expect(canvas.queryByRole('link', { name })).not.toBeInTheDocument();
      await expect(canvas.getByRole('img', { name })).toBeInTheDocument();
    }

    // The safe channel is unaffected — degradation is per-channel, not all-or-nothing.
    await expect(canvas.getByRole('link', { name: /email us/i })).toHaveAttribute('href', 'mailto:care@zimmermann.com');
  },
};

/**
 * The path SFCC-55 actually ships. Its AC scopes the Stay in Touch section to "an email input
 * field and submit button as a placeholder component" and defers the Omneo sign-up, so a valid
 * email resolves straight to the placeholder message with no name-capture modal.
 */
